-- Fase 7: Productos, tarifas y ventas
insert into public.permisos(codigo,modulo,accion,descripcion) values
('productos.ver','productos','ver','Consultar catálogos y tarifas'),('productos.administrar','productos','administrar','Administrar catálogos y tarifas'),('ventas.ver','ventas','ver','Consultar ventas'),('ventas.crear','ventas','crear','Registrar ventas'),('ventas.descuento','ventas','descuento','Autorizar descuentos') on conflict(codigo) do nothing;
insert into public.roles_permisos(rol_id,permiso_id) select r.id,p.id from public.roles r cross join public.permisos p where r.nombre in('Superadministrador','Propietario') and p.modulo in('productos','ventas') on conflict do nothing;
create table if not exists public.materiales(id uuid primary key default gen_random_uuid(),nombre text not null unique,descripcion text,activo boolean not null default true,creado_por uuid not null default auth.uid() references public.perfiles(id),created_at timestamptz not null default now());
create table if not exists public.filtros(id uuid primary key default gen_random_uuid(),nombre text not null unique,descripcion text,activo boolean not null default true,creado_por uuid not null default auth.uid() references public.perfiles(id),created_at timestamptz not null default now());
create table if not exists public.tratamientos(id uuid primary key default gen_random_uuid(),nombre text not null unique,descripcion text,activo boolean not null default true,creado_por uuid not null default auth.uid() references public.perfiles(id),created_at timestamptz not null default now());
create table if not exists public.tarifas_productos(id uuid primary key default gen_random_uuid(),material_id uuid not null references public.materiales(id),filtro_id uuid not null references public.filtros(id),tratamiento_id uuid not null references public.tratamientos(id),precio numeric(12,2) not null check(precio>=0),vigente_desde date not null,activo boolean not null default true,creado_por uuid not null default auth.uid() references public.perfiles(id),created_at timestamptz not null default now(),unique(material_id,filtro_id,tratamiento_id,vigente_desde));
create table if not exists public.ventas(id uuid primary key default gen_random_uuid(),numero_venta text not null unique default('VT-'||upper(substr(gen_random_uuid()::text,1,8))),consulta_id uuid not null references public.consultas_optometricas(id),paciente_id uuid not null references public.pacientes(id),jornada_id uuid not null references public.jornadas(id),brigada_id uuid references public.brigadas(id),vendedor_id uuid not null default auth.uid() references public.perfiles(id),subtotal numeric(12,2) not null,descuento numeric(12,2) not null default 0,total numeric(12,2) not null,abono numeric(12,2) not null default 0,saldo numeric(12,2) not null,metodo_pago text,fecha_entrega date,estado text not null default 'registrada' check(estado in('registrada','pagada','pendiente','entregada','anulada')),observaciones text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ventas_detalle(id uuid primary key default gen_random_uuid(),venta_id uuid not null references public.ventas(id) on delete cascade,material_id uuid not null references public.materiales(id),filtro_id uuid not null references public.filtros(id),tratamiento_id uuid not null references public.tratamientos(id),cantidad integer not null check(cantidad>0),precio_unitario numeric(12,2) not null,subtotal numeric(12,2) not null);
alter table public.movimientos_financieros drop constraint if exists movimientos_financieros_tipo_check;
alter table public.movimientos_financieros add constraint movimientos_financieros_tipo_check check(tipo in('abono_agendamiento','pago_brigada','pago_venta','aplicacion_saldo_favor','devolucion','ajuste','anulacion'));
alter table public.movimientos_financieros add column if not exists venta_id uuid references public.ventas(id);
create or replace function public.registrar_venta(p_consulta uuid,p_material uuid,p_filtro uuid,p_tratamiento uuid,p_cantidad integer,p_descuento numeric,p_abono numeric,p_metodo text,p_entrega date,p_observaciones text) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_c public.consultas_optometricas%rowtype;v_t public.tarifas_productos%rowtype;v_sub numeric;v_total numeric;v_id uuid;begin select * into v_c from public.consultas_optometricas where id=p_consulta;if not found then raise exception 'Consulta no encontrada';end if;select * into v_t from public.tarifas_productos where material_id=p_material and filtro_id=p_filtro and tratamiento_id=p_tratamiento and activo and vigente_desde<=current_date order by vigente_desde desc limit 1;if not found then raise exception 'Esta combinación no tiene un precio configurado';end if;if coalesce(p_descuento,0)>0 and not public.tiene_permiso('ventas.descuento') then raise exception 'No tiene permiso para aplicar descuentos';end if;v_sub=v_t.precio*p_cantidad;v_total=v_sub-coalesce(p_descuento,0);if v_total<0 or coalesce(p_abono,0)>v_total then raise exception 'Valores financieros inválidos';end if;insert into public.ventas(consulta_id,paciente_id,jornada_id,brigada_id,subtotal,descuento,total,abono,saldo,metodo_pago,fecha_entrega,estado,observaciones) values(v_c.id,v_c.paciente_id,v_c.jornada_id,v_c.brigada_id,v_sub,coalesce(p_descuento,0),v_total,coalesce(p_abono,0),v_total-coalesce(p_abono,0),p_metodo,p_entrega,case when coalesce(p_abono,0)=v_total then 'pagada' else 'pendiente' end,p_observaciones) returning id into v_id;insert into public.ventas_detalle(venta_id,material_id,filtro_id,tratamiento_id,cantidad,precio_unitario,subtotal) values(v_id,p_material,p_filtro,p_tratamiento,p_cantidad,v_t.precio,v_sub);if coalesce(p_abono,0)>0 then insert into public.movimientos_financieros(paciente_id,jornada_id,brigada_id,venta_id,tipo,valor,metodo_pago,canal) values(v_c.paciente_id,v_c.jornada_id,v_c.brigada_id,v_id,'pago_venta',p_abono,p_metodo,'administracion');end if;return v_id;end;$$;
do $$ declare t text;begin foreach t in array array['materiales','filtros','tratamientos','tarifas_productos','ventas','ventas_detalle'] loop execute format('alter table public.%I enable row level security',t);end loop;end $$;
create policy "materiales lectura" on public.materiales for select to authenticated using(public.tiene_permiso('productos.ver'));create policy "materiales admin" on public.materiales for all to authenticated using(public.tiene_permiso('productos.administrar')) with check(public.tiene_permiso('productos.administrar'));
create policy "filtros lectura" on public.filtros for select to authenticated using(public.tiene_permiso('productos.ver'));create policy "filtros admin" on public.filtros for all to authenticated using(public.tiene_permiso('productos.administrar')) with check(public.tiene_permiso('productos.administrar'));
create policy "tratamientos lectura" on public.tratamientos for select to authenticated using(public.tiene_permiso('productos.ver'));create policy "tratamientos admin" on public.tratamientos for all to authenticated using(public.tiene_permiso('productos.administrar')) with check(public.tiene_permiso('productos.administrar'));
create policy "tarifas lectura" on public.tarifas_productos for select to authenticated using(public.tiene_permiso('productos.ver'));create policy "tarifas admin" on public.tarifas_productos for all to authenticated using(public.tiene_permiso('productos.administrar')) with check(public.tiene_permiso('productos.administrar'));
create policy "ventas lectura" on public.ventas for select to authenticated using(public.tiene_permiso('ventas.ver'));create policy "ventas crear" on public.ventas for insert to authenticated with check(public.tiene_permiso('ventas.crear'));
create policy "detalle lectura" on public.ventas_detalle for select to authenticated using(public.tiene_permiso('ventas.ver'));create policy "detalle crear" on public.ventas_detalle for insert to authenticated with check(public.tiene_permiso('ventas.crear'));
grant select,insert,update on public.materiales,public.filtros,public.tratamientos,public.tarifas_productos,public.ventas,public.ventas_detalle to authenticated;grant execute on function public.registrar_venta(uuid,uuid,uuid,uuid,integer,numeric,numeric,text,date,text) to authenticated;notify pgrst,'reload schema';
